function loadEnv() {
    const envPath = path.join(__dirname, '.env.test');

    if (fs.existsSync(envPath)) {
        const envContent = fs.readFileSync(envPath, 'utf8');
        const envConfig = {};

        // Parse .env file manually (simple parser)
        const lines = envContent.split('\n');
        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip empty lines and comments
            if (trimmedLine === '' || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse KEY=VALUE
            const separatorIndex = trimmedLine.indexOf('=');
            if (separatorIndex > 0) {
                const key = trimmedLine.substring(0, separatorIndex).trim();
                const value = trimmedLine.substring(separatorIndex + 1).trim();
                envConfig[key] = value;
            }
        }

        return envConfig;
    }

    return {};
}

function getDatabaseUrl() {
    const env = loadEnv();
    return env.DATABASE_URL || process.env.DATABASE_URL;
}

function getMigrations() {
    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log('Migrations directory not found: ./migrations/');
        return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files (files with .sql extension)
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files alphabetically (or you could implement timestamp-based sorting)
    sqlFiles.sort();

    return sqlFiles;
}

function runMigrations() {
    console.log('Starting database migrations...\n');

    // Connect to database
    const dbUrl = getDatabaseUrl();
    if (dbUrl) {
        console.log(`Connecting to database using ${dbUrl.split('@')[1] || 'DATABASE_URL'}...`);
        console.log('Connected successfully.\n');
    } else {
        console.log('No DATABASE_URL found, skipping database connection.\n');
    }

    const migrations = getMigrations();

    if (migrations.length === 0) {
        console.log('No SQL migration files found in ./migrations/');
        return;
    }

    console.log(`Found ${migrations.length} migration file(s):\n`);

    // Log each migration filename in order
    migrations.forEach((filename, index) => {
        console.log(`${index + 1}. ${filename}`);
    });

    console.log('\nMigration processing complete.');
}

// Run the migration script
runMigrations();

// Export for potential use in other modules
module.exports = {
    loadEnv,
    getDatabaseUrl,
    getMigrations,
    runMigrations
};

