const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Database migration script
 * Reads SQL files from the migrations directory and logs each filename in order
 */

async function getMigrationFiles() {
  try {
    const files = await fs.promises.readdir(MIGRATIONS_DIR);

    // Filter only .sql files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort alphabetically (assuming filenames include timestamps or sequential numbers)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
    } else {
      console.error(`Error reading migrations directory: ${error.message}`);
    }
    process.exit(1);
  }
}

async function migrate() {
  console.log('Starting database migration...\n');

  const migrationFiles = await getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  for (const file of migrationFiles) {
    // Log each filename that would be applied
    console.log(`Would apply: ${file}`);
  }

  console.log(`\nTotal: ${migrationFiles.length} migration(s) to apply`);
}

// Run the migration script
migrate().catch(console.error);

