const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from the ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function loadEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Environment file not found: ${filePath}`);
      return null;
    }

    const envContent = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    for (const line of envContent.split('\n')) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) continue;

      const [key, ...valueParts] = trimmedLine.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return null;
  }
}

function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (ending with .sql)
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql')
    );

    // Sort files alphabetically to ensure consistent order
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

function resolveDatabaseUrl() {
  // Try to load from .env.test first
  const envPath = path.join(__dirname, '.env.test');
  const envVars = loadEnvFile(envPath);

  if (envVars && envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  // Fall back to environment variable
  return process.env.DATABASE_URL;
}

function logConnectionInfo() {
  const databaseUrl = resolveDatabaseUrl();

  if (databaseUrl) {
    // Log connection success (without exposing credentials)
    const urlString = String(databaseUrl);
    let sanitizedUrl = urlString;

    // Attempt to sanitize the URL by masking sensitive parts
    try {
      const url = new URL(urlString);
      // Mask password if present
      if (url.password) {
        url.password = '***';
      }
      sanitizedUrl = url.toString();
