const fs = require('fs');
const path = require('path');

// Directory where SQL migration files are stored
const migrationsDir = path.join(__dirname, 'migrations');

// Load environment variables from .env.test
function loadEnvFile(filePath) {
  try {
    const envContent = fs.readFileSync(filePath, 'utf-8');
    const envVars = {};

    for (const line of envContent.split('\n')) {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) continue;

      const [key, ...valueParts] = trimmed.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }

    return envVars;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('Environment file not found:', filePath);
    } else {
      console.error('Error reading environment file:', err.message);
    }
    return {};
  }
}

// Load DATABASE_URL from .env.test
const envPath = path.join(__dirname, '.env.test');
const env = loadEnvFile(envPath);
const databaseUrl = env.DATABASE_URL;

// Log connection info if DATABASE_URL is found
if (databaseUrl) {
  console.log(`Connected successfully to ${databaseUrl}`);
} else {
  console.warn('DATABASE_URL not found in .env.test, skipping connection');
}

// Read and list all SQL files in alphabetical order
try {
  const files = fs.readdirSync(migrationsDir)
    .filter(file => file.endsWith('.sql'))
    .sort();

  console.log('Migration files to apply (in order):');
  files.forEach(file => {
    console.log(`- ${file}`);
  });

  if (files.length === 0) {
    console.log('No migration files found in', migrationsDir);
  }
} catch (err) {
  if (err.code === 'ENOENT') {
    console.error('Migrations directory not found:', migrationsDir);
  } else {
    console.error('Error reading migrations directory:', err.message);
  }
}
